#!/bin/sh
# Regression: the chassis gallery must show each set in the right colour.
#
# The gallery is generated by looping over chassis/*/filter.sh, and those files
# are plain variable assignments. CH_LUMA (set only by the monochrome sets)
# survives into the next set sourced after it, so a colour tube gets folded to
# grey by format=gray and the picture ships black-and-white. That shipped once:
# philips_gr1ax, photon_51tc408d, rubin_51tc, samsung_cs2173 and
# sony_kv_m2180 all had grey strong_signal_color.png while their own tv/
# copy of the same render was in colour.
#
# A colour set must stay colourful and a monochrome set must stay grey, in
# every signal variant. This checks the committed PNGs, so a bad regeneration
# fails here instead of quietly shipping.

ROOT="$(CDPATH= cd -- "$(dirname "$0")/.." && pwd)"

# Sets with no colour decoder: CH_LUMA folds them to luma-only.
MONO="junost_402b junost_406 rassvet_307"

# SATAVG below this reads as grey, above it as colour. Mono sets keep a
# small cast from the white-point tint (aged phosphor warms the grey), so the
# threshold sits above that noise floor.
GREY_MAX=5.0

fails=0
checked=0

for png in "$ROOT"/chassis/*/*.png; do
  [ -f "$png" ] || continue
  chassis=$(basename "$(dirname "$png")")
  signal=$(basename "$png" .png)

  sat=$(ffmpeg -i "$png" -vf "signalstats,metadata=print:key=lavfi.signalstats.SATAVG" \
        -f null - 2>&1 | grep -oE 'SATAVG=[0-9.]+' | cut -d= -f2)
  if [ -z "$sat" ]; then
    echo "FAIL: $chassis/$signal.png unreadable"
    fails=$((fails + 1))
    continue
  fi
  checked=$((checked + 1))

  expect=colour
  for m in $MONO; do
    [ "$m" = "$chassis" ] && expect=grey
  done

  if [ "$expect" = "grey" ]; then
    if awk -v s="$sat" -v t="$GREY_MAX" 'BEGIN{exit !(s < t)}'; then
      printf 'ok:   %-20s %-20s grey (SATAVG=%s)\n' "$chassis" "$signal" "$sat"
    else
      printf 'FAIL: %-20s %-20s should be grey, SATAVG=%s\n' "$chassis" "$signal" "$sat"
      fails=$((fails + 1))
    fi
  else
    if awk -v s="$sat" -v t="$GREY_MAX" 'BEGIN{exit !(s >= t)}'; then
      printf 'ok:   %-20s %-20s colour (SATAVG=%s)\n' "$chassis" "$signal" "$sat"
    else
      printf 'FAIL: %-20s %-20s should be colour, SATAVG=%s (grey leak?)\n' "$chassis" "$signal" "$sat"
      fails=$((fails + 1))
    fi
  fi
done

echo "---"
if [ "$fails" -eq 0 ]; then
  echo "PASS: $checked chassis screenshots have the right colour"
  exit 0
fi
echo "FAIL: $fails of $checked chassis screenshots have the wrong colour"
exit 1
